:root {
  --bg: #ffffff;
  --header-bg: #2d6a4f;
  --header-text: #ffffff;
  --accent: #74c69d;
  --pill-bg: #d8f3dc;
  --pill-text: #1b4332;
  --label-color: #6b7280;
  --value-color: #111827;
  --border: #e5e7eb;
  --body-bg: #f9fafb;
}

.camp-badge {
  background-color: var(--bg);
  border: 1px solid var(--border);
  border-radius: 16px;
  overflow: hidden;
  width: 360px;
  margin: 40px auto;
}

.badge-header {
  background-color: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
}

.camp-icon {
  font-size: 28px;
  line-height: 1;
}

.camp-title {
  flex: 1;
}

.camp-name {
  font-size: 18px;
  font-weight: 700;
  color: var(--header-text);
  margin: 0;
  line-height: 1.2;
}

.camp-session {
  font-size: 12px;
  color: var(--accent);
  margin: 2px 0 0;
}

.status-pill {
  background-color: var(--pill-bg);
  color: var(--pill-text);
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 999px;
}

.badge-body {
  background-color: var(--body-bg);
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.info-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 14px;
}

.label {
  color: var(--label-color);
  font-weight: 500;
}

.value {
  color: var(--value-color);
  font-weight: 600;
}
